        if (res.id != undefined) {
            result['邮箱'] = res.email
            putLoginInfo(JSON.stringify(result))
            let devices
            try {
                devices = Object.keys(JSON.parse(res.device)).length;
            } catch (e) {
                devices = res.device ? 1 : 0;
            }
            let isVip = isVips(res);
            tips = `
┏┅┅┅┅┅┅┱┄┄┄┄┄┄┄┄┄┄┐
