ruleSearch.bookList:
class.cytable@tag.tr[1:20]@tag.a[1]||$.items[:20]
<js>
list=result.toArray();
json=[];
for(i in list){
id=String(list[i]).match(/href/)?String(list[i].attr("href")).match(/(\d+)/)[1]:list[i].novelid;
url="http://www.jjwxc.net/onebook.php?novelid="+id;
html=String(java.ajax(url));
java.setContent(html);
J=org.jsoup.Jsoup.parse(html);

des=String(J.select("span[style='color:#F98C4D']").text()).replace(/立意：/,'◎ ').replace(/一句话简介：/,'◎ ')+"◎"+java.getElement("id.novelintro").text();
title=J.select('h1[itemprop="name"]').text();
author=J.select('span[itemprop="author"]').text();
cover=J.select(".noveldefaultimage").attr("src");
if(/(?:postimg|bmp|alicdn)\./.test(cover)){
	cover = "https://i9-static.jjwxc.net/novelimage.php?novelid="+id
	}
cat=String(J.select('a[style="text-decoration:none;color: red;"]').text()).replace(/\s/g,',');
status=J.select('span[itemprop="updataStatus"]').text();
size=String(J.select('span[itemprop="wordCount"]').text()).replace(/字/,'');
n=String(java.getElement('@@id.oneboolt@tag.tr.-2@span').text()).replace(/\n/,'•').replace(/\*最新更新/,'').replace(/(.*?)\[VIP\]/,'🔒$1');
num=java.getElement('@@id.oneboolt@tag.tr.-2@tag.td.0').text();
genre=J.select('[itemprop="genre"]').text().split('-')[1];
json.push({
title:title,
author:author,
cat:status+","+cat+','+genre,
size:size,
url:"http://app-cdn.jjwxc.net/androidapi/novelbasicinfo?novelId="+id,
des:des,
new:String(num+"、"+n).replace(/(\d+、)🔒/,'🔒$1'),
cover:cover
})
}
json
</js>

ruleToc.chapterList:
$.chapterlist
<js>
function readEncrypt(novelid,flag) {
     	FORUMSIGNTAG = 1;
       READSIGNTAG = 0;
	      strArr = [cookie.getKey('http://m.jjwxc.net','sid'),novelid,"autosubscribe",flag];

	      sb = new Date().getTime().toString();
         length = strArr.length;
        for ( i2 = READSIGNTAG; i2 < length; i2 += FORUMSIGNTAG) {
            str = strArr[i2];
            sb+=":";
            sb+=str;
        }

	    en= java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(sb)

	      body = "versionCode=287&sign="+en;
option = {
	method:"POST",
	body:String(body)
	}
url = "https://android.jjwxc.com/androidapi/autoSubscribe,"+JSON.stringify(option); java.longToast(JSON.parse(java.ajax(url)).message)
    }

 if(/(开启|关闭)购买/.test(book.getVariable("custom"))){
 	a = /关闭购买/.test(book.getVariable("custom"))?"cancel":(/开启购买/.test(book.getVariable("custom"))?"open":"cancel");
 	readEncrypt(JSON.parse(result)[0].novelid,a)
 	}

result = result=="[]"?JSON.stringify([{"chaptername":"暂无目录","chapterid":"","islock":"0"}]):result;
</js>
$.[*]

