function LoginToken(token){
	const {java} = this;
	try{
	token = String(token).replace(/undefined|token=|\s|&.*/g,'');
	if(!/\d+_\w{32}/.test(token)){
		java.toast("token值可能有误，请检查填写的token值")
	}

	let fl = this.Map("fl")==""?"9,10":this.Map("fl");
	let search = this.Map("search")==""?"1,8":this.Map("search");
	let bq = this.Map("bq")==""?"5":this.Map("bq");	
	let at = this.M("作者列表（作者::作者id 注意添加多个用空格分割）");
	let classNum = this.Map("classNum");

	this.setHeaders(
		`token=${token}`,
		`fl=${fl}`,
		`bq=${bq}`,
		`classNum=${classNum}`,
		`at=${java.base64Encode(at)}`,
		`search=${search}`
	)
}catch(e){
	java.log(e);
	}
}

function refreshToken(t,code){
