bookInfoRule.init:
@js:
X = (x) =>java.getString(x);
({
    n: X("[property$=book_name]@content"),
    a: X("[property$=author]@content"),
    k: X("[property~=category|status|update_time]@content"),
    w: X("text.字数@text").match(/(\d+)/)[1]+"万",
    l: X("[property~=las?test_chapter_name]@content"),
    i: X("[property$=description]@content\#\#^.*(简介|完结】|番外】)[：:]*|《{{book.name}}》"),
    c: X("[property$=image]@content"),
    t: X("text.查看目录@href")
});

source.exploreUrl:
@js:
    sort = [];
    push = (title, url, type) =>  
    sort.push({
        title: title,
        url: url,
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: type
       }
     });
     push("༺ˇ»`ʚ全部分类ɞ´«ˇ༻", "", "1")
     url = source.getKey();
     o = org.jsoup.Jsoup.parse(java.ajax(url));
     s = o.select('div[class="nav_c clear"] li a');
     for(i in s){
         if(i >= 1){
         u = String(s[i].attr("href")).replace(/(.*)\/1\.html/,"$1/{{page}}.html");
         push(s[i].text(), u, "0.25")
       }
     };
    JSON.stringify(sort);

